import{_ as t,o,c,a2 as a}from"./chunks/framework.CvydjLy7.js";const T=JSON.parse('{"title":"9.14 小结与下一步","description":"","frontmatter":{"title":"9.14 小结与下一步"},"headers":[],"relativePath":"ch09/14.md","filePath":"ch09/14.md","lastUpdated":1789497795000}'),i={name:"ch09/14.md"};function n(s,e,r,d,l,p){return o(),c("div",null,[...e[0]||(e[0]=[a('<h1 id="_9-14-小结与下一步" tabindex="-1">9.14 小结与下一步 <a class="header-anchor" href="#_9-14-小结与下一步" aria-label="Permalink to &quot;9.14 小结与下一步&quot;">​</a></h1><p>这一篇做的事：</p><ul><li>测试分四层，用实测耗时说明为什么“能写在低层就不要往上走”（单元 0.68 s / Web 切片 0.31 s / JPA 切片 0.56 s / 整体 2.43 s / 条件装配 0.02 s）</li><li>4.x 的测试模块拆分：一批 <code>-test</code> 后缀的细粒度模块，以及<strong>注解包名的迁移对照表</strong></li><li><code>@MockitoBean</code> 取代 <code>@MockBean</code>；<code>MockMvcTester</code> 的 AssertJ 风格；<code>extractingPath</code> 不能链式调用</li><li><code>@DataJpaTest</code> 的三个默认行为（内嵌库、事务回滚、显示 SQL），以及 <code>Replace.NONE</code> 的含义</li><li>四种 <code>webEnvironment</code> 模式的取舍，<strong>真实端口下 <code>@Transactional</code> 不回滚服务端数据</strong></li><li>五种 HTTP 测试客户端的适用场景；<code>TestRestTemplate</code> 是<strong>搬迁</strong>不是废弃，且额外需要 <code>spring-boot-restclient</code></li><li><code>ApplicationContextRunner</code> 测条件装配（4 个用例 0.02 秒），以及 <code>havingValue</code> 是字符串精确比较</li><li>Testcontainers 的用法与实测数据（MySQL 8.4.9，容器地址与数据源一致），容器 Bean 与 JUnit 扩展的生命周期差异</li><li><strong>Testcontainers 2.0 的四项变化</strong>：数据库容器移出 core、坐标名加了前缀、包名搬进技术栈命名空间、去掉自引用泛型</li><li>没有 Docker / 拉不到镜像时的三种处理</li></ul><p>工程侧新增 <code>activity-server-testing</code>，31 个用例、15.8 秒全绿，四层各有覆盖。</p><p>下一篇从“写完的代码怎么上线”接上：Actuator 暴露哪些端点、健康检查怎么自定义、指标怎么读、日志级别怎么在不重启的情况下调整，以及为什么这些端点在暴露之前必须先加安全约束。</p><hr>',6)])])}const g=t(i,[["render",n]]);export{T as __pageData,g as default};
